const TS_COLORS = ['#0088cc', '#2e9461', '#d97706', '#6d4aff', '#c2410c', '#202a44'];

function isAdditiveMetric(unit: string | undefined, label = ''): boolean {
  const u = (unit ?? '').trim().toLowerCase();
  if (!u) return false;
  if (u.includes('%') || u.includes('°c') || u.includes('ppm') || u.includes('ms') || u.includes('m²') || u.includes('/m2') || u.includes('db') || u.includes('lx')) {
    return false;
  }
  if (label.includes('率') || label.includes('均') || label.includes('强度') || label.includes('延迟')) {
    return false;
  }
  return true;
}

function scaleNumber(val: number, factor: number): number {
  const scaled = val * factor;
  return Math.abs(scaled) >= 10 ? Math.round(scaled) : Math.round(scaled * 10) / 10;
}

function formatKpiDisplay(rawVal: string, unit?: string): { value: string; unit: string; title: string } {
  const num = Number(String(rawVal).replaceAll(',', ''));
  const u = unit ?? '';
  if (!Number.isFinite(num)) return { value: rawVal, unit: u, title: `${rawVal} ${u}`.trim() };
  if (u === 'kWh' && Math.abs(num) >= 10000) {
    return {
      value: (num / 1000).toFixed(1),
      unit: 'MWh',
      title: `精确值：${num.toLocaleString('en-US')} kWh`,
    };
  }
  return {
    value: Number.isInteger(num) ? num.toLocaleString('en-US') : num.toLocaleString('en-US', { maximumFractionDigits: 1 }),
    unit: u,
    title: `${num.toLocaleString('en-US')} ${u}`.trim(),
  };
}

function buildScopedReport(base: AnalysisReport, factor: number): AnalysisReport {
  if (factor === 1) return base;
  const scaleSeries = isAdditiveMetric(base.unit);
  return {
    ...base,
    kpis: base.kpis.map((k) => {
      const num = Number(String(k.value).replaceAll(',', ''));
      if (!Number.isFinite(num) || !isAdditiveMetric(k.unit, k.label)) return k;
      return { ...k, value: String(scaleNumber(num, factor)) };
    }),
    series: scaleSeries
      ? base.series.map((pt) => ({
          ...pt,
          value: scaleNumber(pt.value, factor),
          ...(typeof pt.baseline === 'number' ? { baseline: scaleNumber(pt.baseline, factor) } : {}),
        }))
      : base.series,
    zoneBreakdown: base.zoneBreakdown.map((z) =>
      isAdditiveMetric(z.unit) ? { ...z, value: scaleNumber(z.value, factor) } : z
    ),
  };
}

function renderSvgChart(report: AnalysisReport, showEvents: boolean): string {
  const maxVal = Math.max(...report.series.map((s) => Math.max(s.value, s.baseline ?? 0)), 1);
  const barW = 46;
  const gap = 34;
  const padL = 36;
  const chartW = Math.max(report.series.length * (barW + gap) + padL * 2, 620);
  const chartH = 228;
  const baseY = 184;
  const plotH = 132;

  const gridLines = [0, 0.25, 0.5, 0.75, 1]
    .map((ratio) => {
      const y = Math.round(baseY - ratio * plotH);
      return `<line x1="${padL - 8}" y1="${y}" x2="${chartW - 18}" y2="${y}" stroke="oklch(85.12% 0 107 / 0.55)" stroke-dasharray="${ratio === 0 ? '0' : '3 3'}" />`;
    })
    .join('');

  const bars = report.series
    .map((pt, i) => {
      const x = padL + i * (barW + gap);
      const h = Math.max(8, Math.round((pt.value / maxVal) * plotH));
      const y = baseY - h;
      const isOverBaseline = typeof pt.baseline === 'number' && pt.value > pt.baseline * 1.08;
      const faultShade = isOverBaseline
        ? `<rect x="${x - 8}" y="34" width="${barW + 16}" height="${baseY - 34}" rx="8" fill="oklch(58.53% 0.2203 26.56 / 0.09)" />`
        : '';
      const baseLineMark =
        typeof pt.baseline === 'number'
          ? `<line x1="${x - 5}" y1="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" x2="${x + barW + 5}" y2="${Math.round(baseY - (pt.baseline / maxVal) * plotH)}" stroke="var(--pacom-brand)" stroke-width="1.5" stroke-dasharray="3 2" opacity="0.6" />`
          : '';
      const eventMarker =
        showEvents && (isOverBaseline || i === 1)
          ? `<g><title>${isOverBaseline ? '事件：告警触发 / 负荷超基线' : '事件：执行节能排程下发'}</title><circle cx="${x + barW / 2}" cy="18" r="7" fill="${isOverBaseline ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'}" /><text x="${x + barW / 2}" y="21" text-anchor="middle" font-size="8.5" font-weight="600" fill="#fff">${isOverBaseline ? '!' : 'S'}</text></g>`
          : '';
      const labelNum = pt.value >= 10000 ? `${(pt.value / 1000).toFixed(1)}k` : pt.value.toLocaleString('en-US');
      return `
        ${faultShade}
        ${baseLineMark}
        ${eventMarker}
        <g>
          <title>${pt.label}：实测 ${pt.value.toLocaleString('en-US')} ${report.unit}${pt.baseline !== undefined ? ` / 基线 ${pt.baseline.toLocaleString('en-US')} ${report.unit}` : ''}</title>
          <rect x="${x}" y="${y}" width="${barW}" height="${h}" rx="7" fill="${isOverBaseline ? 'var(--pacom-status-warning)' : 'var(--pacom-accent-solid)'}" opacity="0.88" />
        </g>
        <text x="${x + barW / 2}" y="${y - 8}" text-anchor="middle" font-size="11" font-weight="500" fill="var(--pacom-text-primary)">${labelNum}</text>
        <text x="${x + barW / 2}" y="${baseY + 22}" text-anchor="middle" font-size="11" fill="var(--pacom-text-secondary)">${pt.label}</text>
      `;
    })
    .join('');

  return `
    <svg viewBox="0 0 ${chartW} ${chartH}" style="width:100%; height:232px; display:block;" role="img" aria-label="${report.category} 趋势图">
      ${gridLines}
      ${bars}
    </svg>
  `;
}

